import type { ArchEdge, ArchNode, Design, Tier } from "@/lib/types";

const ASK = {
  req: "List functional requirements, explicit non-goals, and non-functional targets (scale, latency, availability, consistency).",
  est: "Estimate QPS (average and peak), storage growth and anything else that will drive a design decision.",
  api: "Define the core API endpoints and the data model: entities, keys, and which store holds each.",
  hl: "Describe the high-level architecture and walk one read and one write through it.",
  deep: "Pick the two or three hardest parts and go deep: algorithms, data structures, failure handling.",
  wrap: "Bottlenecks, failure modes, monitoring, and how the design evolves at 10× scale.",
};

/** nodes: "id|label|kind|x|y|note"; edges: "a>b|label" (sync) or "a~b|label" (async) */
export function arch(nodes: string[], edges: string[]): { nodes: ArchNode[]; edges: ArchEdge[] } {
  return {
    nodes: nodes.map((n) => {
      const [id, label, kind, x, y, note] = n.split("|");
      return { id, label, kind: kind as ArchNode["kind"], x: +x, y: +y, note };
    }),
    edges: edges.map((e) => {
      const [path, label] = e.split("|");
      const async = path.includes("~");
      const [a, b] = path.split(async ? "~" : ">");
      return { a, b, label, async };
    }),
  };
}

export function H(
  id: string, topic: string, title: string, tier: Tier, prompt: string,
  s: { req: string; est: string; api: string; hl: string; deep: string; wrap: string },
  steer: [string, string][], pitfalls: string[], level: string,
  a: { nodes: ArchNode[]; edges: ArchEdge[] },
): Design {
  return {
    id: `d-${id}`, area: "hld", topic, title, tier, est: 60, prompt,
    stages: (Object.keys(ASK) as (keyof typeof ASK)[]).map((k) => ({
      key: k,
      title: { req: "Requirements", est: "Estimation", api: "API & data model", hl: "High-level design", deep: "Deep dives", wrap: "Wrap-up" }[k],
      ask: ASK[k],
      model: s[k],
    })),
    steer, pitfalls, level, arch: a,
  };
}

